const ROOT = process.cwd();
const MARK = "aura-links-youtube-fix-setup.cjs";
const LINKS = "Added by aura-messages-links-setup.cjs";
const BAK = ".before-youtube-fix.bak";
const say = (s = "") => console.log(s);
const full = (rel) => path.join(ROOT, ...rel.split("/"));
const stop = (lines) => { say("\nNothing was changed."); lines.forEach((l) => say("  " + l)); say(); process.exit(1); };
const ALL = ["src/components/messages.jsx", "electron/linkpreview.js", "tests/link-preview.cjs", "tests/message-links.cjs"];
if (!fs.existsSync(full("package.json"))) stop(["This isn't your AURA project folder (no package.json here)."]);
if (process.argv.includes("--undo")) {
  let n = 0;
  for (const rel of ALL) if (fs.existsSync(full(rel) + BAK)) { fs.copyFileSync(full(rel) + BAK, full(rel)); fs.unlinkSync(full(rel) + BAK); say("  restored  " + rel); n++; }
  say(n ? "\nUndo finished.\n" : "\nNothing to undo.\n");
  process.exit(0);
}
const plan = [];
for (const rel of ALL) {
  if (!fs.existsSync(full(rel))) { if (rel.startsWith("tests/")) continue; stop([rel + " isn't there. Run aura-messages-links-setup.cjs first, then this again."]); }
  const raw = fs.readFileSync(full(rel), "utf8");
  const eol = raw.includes("\r\n") ? "\r\n" : "\n";
  const text = raw.replace(/\r\n/g, "\n");
  if (text.includes(MARK)) { plan.push({ rel, done: true }); continue; }
  if (!text.includes(LINKS)) stop([rel + " doesn't have link previews yet. Run aura-messages-links-setup.cjs first, then this again."]);
  let out = text;
  if (rel === "src/components/messages.jsx") {
    for (const e of DATA.edits) {
      const i = out.indexOf(e.find);
      if (i < 0 || out.indexOf(e.find, i + 1) >= 0) stop(["In " + rel + " I couldn't find the spot for: " + e.find.trim().split("\n")[0].slice(0, 90), "Copy this message to Claude."]);
      out = out.slice(0, i) + e.replace + out.slice(i + e.find.length);
    }
  } else out = DATA.files[rel];
  plan.push({ rel, text: out, eol });
}
say("\nAURA: YouTube links get their preview\n");
for (const p of plan) {
  if (p.done) { say("  " + p.rel + ": already done"); continue; }
  if (!fs.existsSync(full(p.rel) + BAK)) fs.copyFileSync(full(p.rel), full(p.rel) + BAK);
  fs.writeFileSync(full(p.rel), p.eol === "\n" ? p.text : p.text.replace(/\n/g, p.eol));
  say("  " + p.rel + ": fixed");
}
say("\nDone. Restart AURA. Run  npm test  before your next release.\n");
